arguments.command:
cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && for b in rachel monica phoebe joey chandler ross; do
  echo "===== $b =====";
  git log --reverse --format='%H|%ci' origin/friend/$b | while IFS='|' read sha date; do
    msg=$(git show -s --format='%B' $sha);
    if echo "$msg" | grep -q 'Friend-Message: 1'; then
      ep=$(echo "$msg" | grep '^Episode:' | head -1);
      if echo "$ep" | grep -q 'S05/E21'; then
        echo "$sha $date $ep";
      fi
    fi
  done
done
